<script lang="ts">import MailPassword from './MailPassword.svelte';import {mailCommand,mailId} from '$lib/mail/store';import {quotas} from '$lib/mail/model.js';export let domains:string[];export let onSaved:()=>void=()=>{};export let onCancel:()=>void=()=>{};let local='',domain='',quota=5,password='',error='';$: {if(!domains.includes(domain))domain=domains[0]||'';}function create(){try{if(password.length<8||password.length>128)throw Error('Enter an 8–128 character sample password.');mailCommand({type:'create',id:mailId(),local,domain,quota});password='';onSaved();}catch(e){error=e instanceof Error?e.message:'Mailbox creation failed.';}}</script>
{#if domains.length}<form class="card stack" on:submit|preventDefault={create}><div><h3>Create mailbox</h3><p class="subtitle">Create an email address on your own domain.</p></div><div class="mail-address-fields"><label class="field">Mailbox name<input required maxlength="64" placeholder="info" bind:value={local}/></label><span class="mail-at">@</span><label class="field">Domain<select required bind:value={domain}>{#each domains as d}<option value={d}>{d}</option>{/each}</select></label></div><MailPassword bind:value={password}/><label class="field">Mailbox quota<select bind:value={quota}>{#each quotas as q}<option value={q}>{q} GB</option>{/each}</select></label><small>Mail DNS can be configured after creation. No project is required. Passwords are not stored or usable in the demo.</small>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button type="button" class="btn secondary" on:click={onCancel}>Cancel</button><button class="btn primary" type="submit">Create mailbox</button></div></form>{:else}<section class="card"><h3>No domains available</h3><p class="subtitle">Add your business domain without creating a website.</p><a href="/domains" class="btn primary">Add domain</a></section>{/if}
